import ray
ray.init()

@ray.remote
class Counter:
    def __init__(self):
        self.value = 0
    def increment(self):
        self.value += 1
        return self.value

counter = Counter.remote()
assert ray.get(counter.increment.remote()) == 1
ray.shutdown()

def squares(n):
    for i in range(n):
        yield i * i

assert sum(squares(4)) == 14

from functools import wraps

def logged(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        print(fn.__name__)
        return fn(*args, **kwargs)
    return wrapper

@logged
def add(a, b):
    return a + b

assert add(2, 3) == 5

