WITH ranked AS (
 SELECT *, DENSE_RANK() OVER (
  PARTITION BY dept ORDER BY salary DESC
 ) AS rnk FROM employees
)
SELECT name, dept, salary FROM ranked
WHERE rnk <= 2 ORDER BY dept, salary DESC, name;

